var SL_MAX_LEVEL=16, SL_P=0.5;
function slRng(state){
  var x=state>>>0;
  x^=x<<13; x>>>=0;
  x^=x>>>17;
  x^=x<<5; x>>>=0;
  return x>>>0;
}
function slCreate(seed){
  return { head:{ key:null, val:null, next:new Array(SL_MAX_LEVEL).fill(null) },
    level:1, size:0, rng:(seed===undefined?88675123:seed)>>>0 };
}
function slRandLevel(sl){
  var lvl=1;
  for(;;){
    sl.rng=slRng(sl.rng);
    if((sl.rng%1000)/1000<SL_P && lvl<SL_MAX_LEVEL) lvl++;
    else break;
  }
  return lvl;
}
function slInsert(sl, key, val){
  if(typeof key!=='number'||isNaN(key)) return { ok:false, error:'键必须是数字' };
  var update=new Array(SL_MAX_LEVEL), node=sl.head, i;
  for(i=sl.level-1;i>=0;i--){
    while(node.next[i]&&node.next[i].key<key) node=node.next[i];
    update[i]=node;
  }
  var cand=node.next[0];
  if(cand&&cand.key===key){ cand.val=val===undefined?null:val; return { ok:true, updated:true }; }
  var lvl=slRandLevel(sl);
  if(lvl>sl.level){
    for(i=sl.level;i<lvl;i++) update[i]=sl.head;
    sl.level=lvl;
  }
  var nn={ key:key, val:val===undefined?null:val, next:new Array(lvl).fill(null) };
  for(i=0;i<lvl;i++){
    nn.next[i]=update[i].next[i];
    update[i].next[i]=nn;
  }
  sl.size++;
  return { ok:true, updated:false };
}
function slSearch(sl, key){
  var node=sl.head, i;
  for(i=sl.level-1;i>=0;i--){
    while(node.next[i]&&node.next[i].key<key) node=node.next[i];
  }
  node=node.next[0];
  if(node&&node.key===key) return { found:true, key:node.key, val:node.val };
  return { found:false };
}
function slDelete(sl, key){
  var update=new Array(SL_MAX_LEVEL), node=sl.head, i;
  for(i=sl.level-1;i>=0;i--){
    while(node.next[i]&&node.next[i].key<key) node=node.next[i];
    update[i]=node;
  }
  node=node.next[0];
  if(!node||node.key!==key) return false;
  for(i=0;i<sl.level;i++){
    if(update[i].next[i]===node) update[i].next[i]=node.next[i];
  }
  while(sl.level>1&&!sl.head.next[sl.level-1]) sl.level--;
  sl.size--;
  return true;
}
function slRange(sl, lo, hi){
  var out=[], node=sl.head, i;
  for(i=sl.level-1;i>=0;i--){
    while(node.next[i]&&node.next[i].key<lo) node=node.next[i];
  }
  node=node.next[0];
  while(node&&node.key<=hi){ out.push(node.key); node=node.next[0]; }
  return out;
}
function slToArray(sl){
  var out=[], node=sl.head.next[0];
  while(node){ out.push(node.key); node=node.next[0]; }
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { slCreate:slCreate, slInsert:slInsert, slSearch:slSearch,
    slDelete:slDelete, slRange:slRange, slToArray:slToArray, slRandLevel:slRandLevel, slRng:slRng };
}
if (typeof window !== 'undefined') {
  window.SkipForgePure = { slCreate:slCreate, slInsert:slInsert, slSearch:slSearch,
    slDelete:slDelete, slRange:slRange, slToArray:slToArray, slRandLevel:slRandLevel, slRng:slRng };
}
